using FinSense;
using Microsoft.EntityFrameworkCore;
using System.Text;
using System.Text.Json.Serialization;
using System.Net;
var builder=WebApplication.CreateBuilder(args);
builder.Services.AddDbContext<FinanceDb>(o=>o.UseSqlServer(builder.Configuration.GetConnectionString("Finance")??"Server=.\\SQLEXPRESS;Database=FinSenseAI_Dev;Trusted_Connection=True;TrustServerCertificate=True"));
builder.Services.ConfigureHttpJsonOptions(o=>o.SerializerOptions.ReferenceHandler=ReferenceHandler.IgnoreCycles);
var app=builder.Build();app.UseDefaultFiles();app.UseStaticFiles();
app.UseExceptionHandler(a=>a.Run(async c=>{c.Response.StatusCode=500;await c.Response.WriteAsJsonAsync(new{error="No se pudo completar la operación. Revisá la conexión y los datos."});}));
app.MapGet("/api/health",async(FinanceDb db)=>await db.Database.CanConnectAsync()?Results.Ok(new{status="disponible"}):Results.Problem("Base de datos no disponible.",statusCode:503));
app.MapGet("/api/accounts",async(FinanceDb db)=>await db.Accounts.OrderBy(x=>x.Name).ToListAsync());
app.MapPost("/api/accounts",async(Account x,FinanceDb db)=>{x.Name=x.Name.Trim();x.Currency=x.Currency.Trim().ToUpperInvariant();if(x.Name.Length is <1 or >100||x.Currency.Length!=3||!x.Currency.All(char.IsAsciiLetter))return Results.BadRequest(new{error="Indicá un nombre y moneda ISO de tres letras."});x.Id=0;db.Accounts.Add(x);await db.SaveChangesAsync();return Results.Ok(x);});
app.MapPut("/api/accounts/{id}",async(int id,Account input,FinanceDb db)=>{var x=await db.Accounts.FindAsync(id);if(x is null)return Results.NotFound();if(string.IsNullOrWhiteSpace(input.Name)||input.Name.Length>100)return Results.BadRequest(new{error="Nombre inválido."});x.Name=input.Name.Trim();x.Description=input.Description;x.Active=input.Active;await db.SaveChangesAsync();return Results.Ok(x);});
app.MapGet("/api/categories",async(FinanceDb db)=>await db.Categories.OrderBy(x=>x.Name).ToListAsync());
app.MapPost("/api/categories",async(Category x,FinanceDb db)=>{if(string.IsNullOrWhiteSpace(x.Name)||x.Name.Length>80||x.Type is not("ingreso" or "gasto"))return Results.BadRequest(new{error="Categoría inválida."});x.Id=0;db.Categories.Add(x);await db.SaveChangesAsync();return Results.Ok(x);});
app.MapGet("/api/rules",async(FinanceDb db)=>await db.Rules.Include(x=>x.Category).OrderBy(x=>x.Priority).ThenBy(x=>x.Id).ToListAsync());
app.MapPost("/api/rules",async(Rule x,FinanceDb db)=>{var c=await db.Categories.FindAsync(x.CategoryId);if(string.IsNullOrWhiteSpace(x.Pattern)||x.Pattern.Length>100||x.Match is not("exacta" or "contiene")||c is null||!c.Active||c.Type!=x.Type)return Results.BadRequest(new{error="Regla o categoría inválida."});x.Id=0;x.Category=null;db.Rules.Add(x);await db.SaveChangesAsync();return Results.Ok(x);});
app.MapPut("/api/rules/{id}",async(int id,Rule input,FinanceDb db)=>{var x=await db.Rules.FindAsync(id);var c=await db.Categories.FindAsync(input.CategoryId);if(x is null)return Results.NotFound();if(string.IsNullOrWhiteSpace(input.Pattern)||input.Pattern.Length>100||input.Match is not("exacta" or "contiene")||c is null||!c.Active||c.Type!=input.Type)return Results.BadRequest(new{error="Regla inválida."});x.Pattern=input.Pattern;x.Match=input.Match;x.Type=input.Type;x.CategoryId=input.CategoryId;x.Priority=input.Priority;x.Active=input.Active;await db.SaveChangesAsync();return Results.Ok(x);});
app.MapGet("/api/rules/test",async(string text,string type,FinanceDb db)=>Results.Ok(new{match=Logic.MatchRule(await db.Rules.ToListAsync(),text,type)}));
app.MapGet("/api/movements",async(int accountId,DateOnly? from,DateOnly? to,string? type,string? search,int? categoryId,int? page,FinanceDb db)=>{var q=db.Movements.Include(x=>x.Category).Where(x=>x.AccountId==accountId);if(from!=null)q=q.Where(x=>x.Date>=from);if(to!=null)q=q.Where(x=>x.Date<=to);if(!string.IsNullOrWhiteSpace(type))q=q.Where(x=>x.Type==type);if(!string.IsNullOrWhiteSpace(search))q=q.Where(x=>x.Description.Contains(search));if(categoryId!=null)q=q.Where(x=>x.CategoryId==categoryId);int p=Math.Max(1,page??1);return Results.Ok(new{total=await q.CountAsync(),page=p,items=await q.OrderByDescending(x=>x.Date).ThenByDescending(x=>x.Id).Skip((p-1)*20).Take(20).ToListAsync()});});
app.MapPost("/api/movements",async(Movement x,FinanceDb db)=>{var error=Logic.Validate(x,await db.Accounts.FindAsync(x.AccountId),x.CategoryId==null?null:await db.Categories.FindAsync(x.CategoryId));if(error!=null)return Results.BadRequest(new{error});x.Id=0;x.Origin="manual";x.Active=true;x.ManualCategory=x.CategoryId!=null;db.Movements.Add(x);await db.SaveChangesAsync();return Results.Ok(x);});
app.MapPut("/api/movements/{id}",async(int id,Movement input,FinanceDb db)=>{var x=await db.Movements.FindAsync(id);if(x is null)return Results.NotFound();var account=await db.Accounts.FindAsync(x.AccountId);var cat=input.CategoryId==null?null:await db.Categories.FindAsync(input.CategoryId);input.AccountId=x.AccountId;var error=Logic.Validate(input,account,cat);if(error!=null)return Results.BadRequest(new{error});x.Date=input.Date;x.Description=input.Description;x.Type=input.Type;x.Amount=input.Amount;x.CategoryId=input.CategoryId;x.ManualCategory=true;x.RuleId=null;x.UpdatedAt=DateTime.UtcNow;db.Changes.Add(new(){MovementId=id,Action="edición"});await db.SaveChangesAsync();return Results.Ok(x);});
app.MapPost("/api/movements/{id}/void",async(int id,FinanceDb db)=>{var x=await db.Movements.FindAsync(id);if(x is null)return Results.NotFound();x.Active=false;x.UpdatedAt=DateTime.UtcNow;db.Changes.Add(new(){MovementId=id,Action="anulación"});await db.SaveChangesAsync();return Results.Ok(x);});
app.MapGet("/api/summary",async(int accountId,DateOnly? from,DateOnly? to,FinanceDb db)=>{var a=await db.Accounts.FindAsync(accountId);if(a is null)return Results.NotFound();var q=db.Movements.Include(x=>x.Category).Where(x=>x.AccountId==accountId&&x.Active);if(from!=null)q=q.Where(x=>x.Date>=from);if(to!=null)q=q.Where(x=>x.Date<=to);var v=await q.ToListAsync();var income=v.Where(x=>x.Type=="ingreso").Sum(x=>x.Amount);var expense=v.Where(x=>x.Type=="gasto").Sum(x=>x.Amount);return Results.Ok(new{account=a,income,expense,net=income-expense,unclassified=v.Count(x=>x.CategoryId==null),monthly=v.GroupBy(x=>x.Date.ToString("yyyy-MM")).OrderBy(x=>x.Key).Select(g=>new{month=g.Key,income=g.Where(x=>x.Type=="ingreso").Sum(x=>x.Amount),expense=g.Where(x=>x.Type=="gasto").Sum(x=>x.Amount)}),categories=v.Where(x=>x.Type=="gasto").GroupBy(x=>x.Category?.Name??"Sin clasificar").Select(g=>new{name=g.Key,amount=g.Sum(x=>x.Amount)}).OrderByDescending(x=>x.amount),recent=v.OrderByDescending(x=>x.Date).Take(5)});});
app.MapGet("/api/forecast",async(int accountId,FinanceDb db)=>{var a=await db.Accounts.FindAsync(accountId);if(a is null)return Results.NotFound();try{return Results.Ok(ForecastService.Run(await db.Movements.Where(x=>x.AccountId==accountId).ToListAsync(),DateOnly.FromDateTime(DateTime.UtcNow)));}catch(Exception e) when(e is ArgumentException or InvalidOperationException){return Results.Ok(new{available=false,message="No se pudo entrenar el modelo con esta serie."});}});
app.MapGet("/api/unusual",async(int accountId,FinanceDb db)=>{var rows=await db.Movements.Include(x=>x.Category).Where(x=>x.AccountId==accountId&&x.Active&&x.Type=="gasto"&&x.CategoryId!=null).ToListAsync();var result=new List<object>();foreach(var x in rows){var prior=rows.Where(y=>y.CategoryId==x.CategoryId&&y.Date<x.Date).Select(y=>y.Amount).Order().ToList();if(prior.Count<5)continue;var median=prior[prior.Count/2];if(median>0&&x.Amount>median*2)result.Add(new{x.Id,x.Date,x.Description,x.Amount,category=x.Category?.Name,reason=$"Supera dos veces la mediana de {prior.Count} gastos previos ({median:N2})."});}return Results.Ok(new{items=result,warning="Se requieren cinco gastos previos por categoría. Una señal no confirma fraude."});});
app.MapPost("/api/import/preview",async(HttpRequest req,FinanceDb db)=>{try{var form=await req.ReadFormAsync();var f=form.Files.GetFile("file");if(f is null||!f.FileName.EndsWith(".csv",StringComparison.OrdinalIgnoreCase)||f.Length>5*1024*1024||!int.TryParse(form["accountId"],out var id))return Results.BadRequest(new{error="Seleccioná cuenta y CSV de hasta 5 MB."});using var ms=new MemoryStream();await f.CopyToAsync(ms);var rows=await Logic.Preview(db,id,ms.ToArray());return Results.Ok(new{rows,accepted=rows.Count(x=>x.Status=="válido"),rejected=rows.Count(x=>x.Status=="rechazado"),duplicates=rows.Count(x=>x.Status=="duplicado")});}catch(Exception e) when(e is ArgumentException or DecoderFallbackException or CsvHelper.CsvHelperException){return Results.BadRequest(new{error="CSV inválido: "+e.Message});}}).DisableAntiforgery();
app.MapPost("/api/import/confirm",async(HttpRequest req,FinanceDb db)=>{try{var form=await req.ReadFormAsync();var f=form.Files.GetFile("file");if(f is null||!f.FileName.EndsWith(".csv",StringComparison.OrdinalIgnoreCase)||f.Length>5*1024*1024||!int.TryParse(form["accountId"],out var id))return Results.BadRequest(new{error="Archivo o cuenta inválida."});using var ms=new MemoryStream();await f.CopyToAsync(ms);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var rows=await Logic.Preview(db,id,ms.ToArray());var valid=rows.Where(x=>x.Status=="válido").ToList();if(valid.Count==0)return Results.BadRequest(new{error="No hay filas válidas para importar."});var batch=new ImportBatch{AccountId=id,Filename=Path.GetFileName(f.FileName),Accepted=valid.Count,Rejected=rows.Count(x=>x.Status=="rechazado"),Duplicates=rows.Count(x=>x.Status=="duplicado")};db.Imports.Add(batch);await db.SaveChangesAsync();foreach(var row in valid){row.Movement!.ImportId=batch.Id;db.Movements.Add(row.Movement);}await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(batch);}catch(Exception e) when(e is ArgumentException or DecoderFallbackException or CsvHelper.CsvHelperException){return Results.BadRequest(new{error="CSV inválido: "+e.Message});}}).DisableAntiforgery();
app.MapGet("/api/export",async(int accountId,DateOnly? from,DateOnly? to,FinanceDb db)=>{var a=await db.Accounts.FindAsync(accountId);if(a is null)return Results.NotFound();var q=db.Movements.Include(x=>x.Category).Where(x=>x.AccountId==accountId);if(from!=null)q=q.Where(x=>x.Date>=from);if(to!=null)q=q.Where(x=>x.Date<=to);var items=await q.OrderBy(x=>x.Date).ToListAsync();var b=new StringBuilder("fecha,cuenta,moneda,descripcion,tipo,monto,categoria,estado,origen\r\n");foreach(var x in items)b.AppendLine(string.Join(',',x.Date.ToString("yyyy-MM-dd"),Logic.CsvSafe(a.Name),a.Currency,Logic.CsvSafe(x.Description),x.Type,x.Amount.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture),Logic.CsvSafe(x.Category?.Name??"Sin clasificar"),x.Active?"activo":"anulado",x.Origin));return Results.File(Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(b.ToString())).ToArray(),"text/csv","finsense-transacciones.csv");});
app.MapPost("/api/demo",async(FinanceDb db,IWebHostEnvironment env)=>{await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var a=await db.Accounts.FirstOrDefaultAsync(x=>x.Name=="Demostración FinSense"&&x.Currency=="CRC");if(a!=null)return Results.BadRequest(new{error="La cuenta de demostración ya existe; no se duplicaron datos."});a=new Account{Name="Demostración FinSense",Currency="CRC",Description="Datos sintéticos"};db.Accounts.Add(a);foreach(var pair in new[]{("Salario","ingreso"),("Alimentación","gasto"),("Vivienda","gasto"),("Transporte","gasto")})if(!await db.Categories.AnyAsync(x=>x.Name==pair.Item1&&x.Type==pair.Item2))db.Categories.Add(new(){Name=pair.Item1,Type=pair.Item2});await db.SaveChangesAsync();var bytes=await File.ReadAllBytesAsync(Path.Combine(env.ContentRootPath,"examples","demo.csv"));var rows=await Logic.Preview(db,a.Id,bytes);if(rows.Any(x=>x.Status!="válido"))return Results.BadRequest(new{error="El ejemplo no pasó la validación; no se guardaron cambios."});var batch=new ImportBatch{AccountId=a.Id,Filename="demo.csv",Accepted=rows.Count};db.Imports.Add(batch);await db.SaveChangesAsync();foreach(var row in rows){row.Movement!.Origin="demostración";row.Movement.ImportId=batch.Id;db.Movements.Add(row.Movement);}await db.SaveChangesAsync();await tx.CommitAsync();return Results.Ok(new{accountId=a.Id,count=rows.Count});});
app.MapGet("/api/report",async(int accountId,DateOnly? from,DateOnly? to,FinanceDb db)=>{var a=await db.Accounts.FindAsync(accountId);if(a is null)return Results.NotFound();var q=db.Movements.Include(x=>x.Category).Where(x=>x.AccountId==accountId&&x.Active);if(from!=null)q=q.Where(x=>x.Date>=from);if(to!=null)q=q.Where(x=>x.Date<=to);var v=await q.ToListAsync();var inc=v.Where(x=>x.Type=="ingreso").Sum(x=>x.Amount);var exp=v.Where(x=>x.Type=="gasto").Sum(x=>x.Amount);var categories=string.Join("",v.Where(x=>x.Type=="gasto").GroupBy(x=>x.Category?.Name??"Sin clasificar").Select(g=>$"<li>{WebUtility.HtmlEncode(g.Key)}: {g.Sum(x=>x.Amount):N2}</li>"));var all=await db.Movements.Include(x=>x.Category).Where(x=>x.AccountId==accountId&&x.Active&&x.Type=="gasto"&&x.CategoryId!=null).ToListAsync();var signals=new List<string>();foreach(var x in v.Where(x=>x.Type=="gasto"&&x.CategoryId!=null)){var prior=all.Where(y=>y.CategoryId==x.CategoryId&&y.Date<x.Date).Select(y=>y.Amount).Order().ToList();if(prior.Count>=5&&prior[prior.Count/2]>0&&x.Amount>2*prior[prior.Count/2])signals.Add($"<li>{x.Date}: {WebUtility.HtmlEncode(x.Description)} · {x.Amount:N2} · supera dos veces la mediana de {prior.Count} gastos previos ({prior[prior.Count/2]:N2}).</li>");}string forecastText;try{var forecast=ForecastService.Run(await db.Movements.Where(x=>x.AccountId==accountId).ToListAsync(),DateOnly.FromDateTime(DateTime.UtcNow));using var json=System.Text.Json.JsonDocument.Parse(System.Text.Json.JsonSerializer.Serialize(forecast));var root=json.RootElement;forecastText=root.GetProperty("available").GetBoolean()?$"Estimación para {root.GetProperty("month").GetString()}: {root.GetProperty("forecast").GetSingle():N2} {WebUtility.HtmlEncode(a.Currency)}. MAE {root.GetProperty("mae").GetSingle():N2}; línea base {root.GetProperty("baselineMae").GetSingle():N2}. No es gasto real ni garantía.":WebUtility.HtmlEncode(root.GetProperty("message").GetString()??"No disponible.");}catch(Exception){forecastText="El pronóstico no está disponible.";}var signalsHtml=signals.Count>0?string.Join("",signals):"<li>No se señalaron movimientos con historial suficiente.</li>";var html=$"<!doctype html><html lang='es'><meta charset='utf-8'><title>Informe FinSense</title><style>body{{font:16px/1.6 sans-serif;max-width:800px;margin:50px auto;padding:0 20px;color:#253d35}}</style><h1>Informe FinSense AI</h1><p>Generado {DateTime.UtcNow:u} · {WebUtility.HtmlEncode(a.Name)} · {a.Currency}<br>Período: {from?.ToString()??"inicio"} a {to?.ToString()??"fin"}</p><h2>Resumen histórico</h2><p>Ingresos: {inc:N2} · Gastos: {exp:N2} · Balance neto: {inc-exp:N2}</p><h2>Gastos por categoría</h2><ul>{categories}</ul><h2>Movimientos inusuales</h2><ul>{signalsHtml}</ul><h2>Pronóstico separado del histórico</h2><p>{forecastText}</p><p>Meses sin registros interpretados como cero; se excluye el mes actual incompleto. Solo incluye movimientos activos. Análisis de demostración, no asesoría financiera.</p></html>";return Results.File(Encoding.UTF8.GetBytes(html),"text/html; charset=utf-8","informe-finsense.html");});

app.Run();
